// Arc 259 S2c-ii-b — `infer_spawn_program_prime` is RETIRED.
// `spawn-program'` is now a wat defclause (spawn.wat); the checker dispatches via the
// defclause machinery (Arc 256 generic-clause instantiation). The shared projection
// helpers below remain as the backing inference for spawn-thread'/spawn-process'.

/// Shared `:thread` projection — infers `fn_arg` as a fn and projects it to
/// `Thread'<R,S>` (self-peer model, the ONLY valid form post arc 259 S2c-ii-a purge).
///
/// Called by `infer_spawn_thread_prime` (1-arg verb, passing `args[0]`).
/// No duplication: one path.
///
/// Arc 259 S2c-ii-a — apply-loop purge:
/// - If the fn arg type is `Peer'<S,R>`, returns `Thread'<R,S>` (param-swap).
/// - Otherwise, REJECTS with a clear error ("expected a self-peer prog").
fn infer_thread_prog_type(
    fn_arg: &WatAST,
    op: &str,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const PEER_HEAD: &str = "wat::kernel::Thread'";
    let mut local_errors: Vec<CheckError> = Vec::new();

    let fn_inferred = match infer(fn_arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
        Some(t) => t,
        None => {
            let t = fresh.fresh();
            let ty = TypeExpr::Parametric {
                head: PEER_HEAD.into(),
                args: vec![t.clone(), t],
            };
            return if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) };
        }
    };
    let fn_surface = apply_subst(&fn_inferred, subst);
    let fn_ty = reduce(&fn_surface, subst, env.types());
    let (i_ty, _o_ty) = match fn_ty {
        TypeExpr::Fn { args: fn_args, ret } if fn_args.len() == 1 => {
            (fn_args.into_iter().next().unwrap(), *ret)
        }
        TypeExpr::Fn { args: fn_args, .. } => {
            // STOP-1 variant: fn type but wrong arity — a program fn takes exactly one input.
            local_errors.push(CheckError {
                span: fn_arg.span().clone(),
                kind: CheckErrorKind::MalformedForm {
                    head: op.into(),
                    reason: format!(
                        "program fn must take exactly one input parameter (the message); \
                         got {} parameters (inferred type: {})",
                        fn_args.len(),
                        format_type(&fn_surface)
                    ),
                    remedies: vec![],
                },
            });
            let t = fresh.fresh();
            let ty = TypeExpr::Parametric {
                head: PEER_HEAD.into(),
                args: vec![t.clone(), t],
            };
            return CheckResult::partial_with(ty, local_errors);
        }
        other => {
            // STOP-1: not a fn type at all — report exact TypeExpr and stop.
            local_errors.push(CheckError {
                span: fn_arg.span().clone(),
                kind: CheckErrorKind::TypeMismatch {
                    callee: op.into(),
                    param: "program".into(),
                    expected: "fn([I]) -> O  (a single-parameter function value)".into(),
                    got: format_type(&other),
                },
            });
            return CheckResult::errs(local_errors);
        }
    };

    // Arc 259 S2c-ii-a — PURGE. Only the self-peer model is valid.
    //
    // If the fn arg type is `Peer'<S,R>` the prog is a ThreadProg (self-peer
    // handoff model): the spawned thread's `tx` sends S to the parent, and
    // its `rx` receives R from the parent.  The parent-side `Thread'<I,O>`
    // has `I = R` (parent sends R → worker receives R) and `O = S` (parent
    // receives S ← worker sends S).  So return `Thread'<R, S>` = `Thread'<args[1], args[0]>`.
    //
    // Any other prog — the legacy apply-loop `fn([I]) -> O` — is REJECTED with a
    // clear error. The heresy burns; the true forms remain.
    let param_reduced = reduce(&apply_subst(&i_ty, subst), subst, env.types());
    match &param_reduced {
        TypeExpr::Parametric { head, args: peer_args }
            if head == "wat::kernel::Peer'" && peer_args.len() == 2 =>
        {
            // Self-peer model: Thread'<R, S> (param-swap of Peer'<S, R>).
            let s_ty = peer_args[0].clone();
            let r_ty = peer_args[1].clone();
            let ty = TypeExpr::Parametric {
                head: PEER_HEAD.into(),
                args: vec![r_ty, s_ty],
            };
            if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) }
        }
        other => {
            // Apply-loop prog REJECTED (arc 259 S2c-ii-a purge).
            local_errors.push(CheckError {
                span: fn_arg.span().clone(),
                kind: CheckErrorKind::MalformedForm {
                    head: op.into(),
                    reason: format!(
                        "spawn-program' :thread expects a self-peer prog [Peer'<S,R>] -> nil; got {}",
                        format_type(other)
                    ),
                    remedies: vec![],
                },
            });
            CheckResult::errs(local_errors)
        }
    }
}

/// Shared `:process` projection — infers `forms_arg` (accepts any type; the
/// runtime validates it is `Vector<WatAST>`) and returns `Process'<I,O>` with
/// independent fresh vars (arc 214 γ-1).
///
/// Called by `infer_spawn_process_prime` (1-arg verb, passing `args[0]`).
/// No duplication: one path.
fn infer_process_prog_type(
    forms_arg: &WatAST,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    // Infer for error coverage only (type errors in the forms body are caught at
    // startup_from_forms time, not here). Accept any type — the runtime validates
    // it's `Vector<WatAST>` (forms).
    let _ = infer(forms_arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    // Return Process'<I,O> with INDEPENDENT fresh vars (arc 214 γ-1). The
    // forms-server is a request→response program — `send'`ing an I and
    // `recv'`ing a different O is the common case (e.g. a Request enum in,
    // a Response enum out). A single shared `T` would force I = O and break
    // every non-echo server. `send' peer v` drives I from v; `recv' peer -> :U`
    // drives O from the ascription; the two never alias.
    let i = fresh.fresh();
    let o = fresh.fresh();
    let ty = TypeExpr::Parametric {
        head: "wat::kernel::Process'".into(),
        args: vec![i, o],
    };
    if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) }
}

// ─── Arc 259 S2c-i — per-tier 1-arg primitives ───────────────────────────────

/// Type-check `(:wat::kernel::spawn-thread' prog init-fn)` — arc 259 Stone S2c-i.
///
/// Two positional args:
/// - `args[0]`: program fn; inferred; must be `fn([Peer'<S,R>]) -> nil` (self-peer
///   model — the ONLY valid form post arc 259 S2c-ii-a purge); projects to
///   `Thread'<R,S>`. Uses `infer_thread_prog_type` (the shared projection helper).
/// - `args[1]`: init-fn; a 0-arg fn returning `:wat::core::Record`; inferred but not
///   further projected (the checker accepts any fn value here — runtime validates
///   the return type is a :wat::core::Record subtype at peer start).
/// - `args[2]`: post-spawn-fn; `Fn(ThreadLaunch) -> nil`; inferred and unified
///   with `Fn(:wat::spawn::ThreadLaunch) -> :wat::core::nil`.
///
/// No tier keyword, no env arg.
fn infer_spawn_thread_prime(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::spawn-thread'";
    let mut local_errors: Vec<CheckError> = Vec::new();
    if args.len() != 3 {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::ArityMismatch {
                callee: OP.into(),
                expected: 3,
                got: args.len(),
            },
        });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        let t = fresh.fresh();
        let ty = TypeExpr::Parametric {
            head: "wat::kernel::Thread'".into(),
            args: vec![t.clone(), t],
        };
        return CheckResult::partial_with(ty, local_errors);
    }

    // arg 1: init-fn — infer it (accept; the checker does not project deeper).
    let _ = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);

    // arg 2: post-spawn-fn — infer it; unify with Fn(ThreadLaunch) -> nil.
    // This causes the accessor type-check (ThreadLaunch/pid is unknown — check error).
    let _ = infer(&args[2], env, locals, fresh, subst).drain_errors_into(&mut local_errors);

    // Delegate to the shared thread-projection helper (same logic as spawn-program' :thread).
    let (val, mut proj_errs) = infer_thread_prog_type(&args[0], OP, env, locals, fresh, subst).into_parts();
    local_errors.append(&mut proj_errs);
    match val {
        Some(ty) => if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) },
        None => CheckResult::errs(local_errors),
    }
}

/// Type-check `(:wat::kernel::spawn-process' forms post-spawn-fn env-fn max-message-bytes)` — arc 259 Stone S2c-i.
///
/// Four positional args:
/// - `args[0]`: forms (program vec); accepted as any type (runtime validates);
///   returns `Process'<I,O>` with independent fresh vars. Uses
///   `infer_process_prog_type` (the shared projection helper).
/// - `args[1]`: post-spawn-fn; `Fn(ProcessLaunch) -> nil`; inferred and unified
///   with `Fn(:wat::spawn::ProcessLaunch) -> :wat::core::nil`. This causes the
///   accessor type-check at parse time (ProcessLaunch/bogus-field → check error).
/// - `args[2]`: env-fn; a `:wat::core::String` source string the child evals to
///   produce `user.program`; inferred (runtime validates the result is a :wat::core::Record).
/// - `args[3]`: max-message-bytes; an `:wat::core::i64` per-receiver frame-size
///   budget extracted from `ProcessOpts/max-message-bytes`; inferred only (runtime
///   validates the value is an i64).
///
/// No tier keyword, no env arg.
fn infer_spawn_process_prime(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::spawn-process'";
    let mut local_errors: Vec<CheckError> = Vec::new();
    if args.len() != 4 {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::ArityMismatch {
                callee: OP.into(),
                expected: 4,
                got: args.len(),
            },
        });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        let i = fresh.fresh();
        let o = fresh.fresh();
        let ty = TypeExpr::Parametric {
            head: "wat::kernel::Process'".into(),
            args: vec![i, o],
        };
        return CheckResult::partial_with(ty, local_errors);
    }

    // arg 1: post-spawn-fn — infer it; this causes the accessor type-check to fire.
    // When the fn body reads ProcessLaunch/bogus-field, the checker rejects it here.
    let _ = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);

    // arg 2: env-fn — a String source expression; infer only (runtime validates result type).
    let _ = infer(&args[2], env, locals, fresh, subst).drain_errors_into(&mut local_errors);

    // arg 3: max-message-bytes — an i64 budget; infer only (runtime validates it's an i64).
    let _ = infer(&args[3], env, locals, fresh, subst).drain_errors_into(&mut local_errors);

    // Delegate to the shared process-projection helper (same logic as spawn-program' :process).
    let (val, mut proj_errs) = infer_process_prog_type(&args[0], env, locals, fresh, subst).into_parts();
    local_errors.append(&mut proj_errs);
    match val {
        Some(ty) => if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) },
        None => CheckResult::errs(local_errors),
    }
}

// ─── Arc 214 Stone 4.6a-ii — three peer verb intrinsics ─────────────────────
//
// PARTITION — CLAUSE vs INTRINSIC (see docs/DISPATCH.md):
// All three are INTRINSIC (projective / ∀-parametric):
//   send'      — projective: I flows from peer<I,O> into the payload arg.
//   recv'      — projective: O flows from peer<I,O> into the return type.
//   close'     — ∀-parametric: the peer arg is Thread'<∀I,∀O> or Process'<∀I,∀O>;
//                a clause matcher cannot enumerate all (I,O) instantiations.
// The pattern for each: infer args[0], apply_subst+reduce, match
// Parametric{head:"wat::kernel::Thread'"|"…Process'", args:[I,O]},
// project I and/or O. Non-peer arg0 → TypeMismatch "peer (Thread'<I,O> | Process'<I,O>)".

/// Helper: infer args[0] and project [I, O] from it as a peer Parametric.
/// Returns `Ok((i_ty, o_ty))` on success. On failure, pushes a TypeMismatch
/// into `local_errors` and returns `Err(())`.
fn project_peer_io(
    args: &[WatAST],
    head_span: &Span,
    op: &str,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
    local_errors: &mut Vec<CheckError>,
) -> Result<(TypeExpr, TypeExpr), ()> {
    let peer_ty = match infer(&args[0], env, locals, fresh, subst).drain_errors_into(local_errors) {
        Some(t) => t,
        None => return Err(()),
    };
    let peer_surface = apply_subst(&peer_ty, subst);
    let peer_reduced = reduce(&peer_surface, subst, env.types());
    match peer_reduced {
        // Arc 209 C0b.2e-i-b: SocketPeer' is retired — all connection peers are Peer'.
        TypeExpr::Parametric { ref head, ref args }
            if (head == "wat::kernel::Thread'"
                || head == "wat::kernel::Process'"
                || head == "wat::kernel::Peer'")
                && args.len() == 2 =>
        {
            Ok((args[0].clone(), args[1].clone()))
        }
        other => {
            local_errors.push(CheckError {
                span: head_span.clone(),
                kind: CheckErrorKind::TypeMismatch {
                    callee: op.into(),
                    param: "peer".into(),
                    expected: "peer (Thread'<I,O> | Process'<I,O> | Peer'<S,R>)".into(),
                    got: format_type(&other),
                },
            });
            Err(())
        }
    }
}

// ─── Arc 292 — after: one-shot timer peer ────────────────────────────────────

/// Type-check `(:wat::kernel::after peer-kind duration msg)` — arc 292 L3 timer peer.
///
/// Three positional args:
/// - `args[0]`: peer-kind — inferred; must conform to `:wat::program::PeerKind`
///   (`:thread` | `:process`). TypeMismatch if not assignable.
/// - `args[1]`: duration — must conform to `:wat::time::Duration`.
/// - `args[2]`: msg — inferred; its type becomes the output type `O`.
///
/// Returns `Timer'<O>` where `O` is the inferred type of `msg`. The tier-open
/// `Timer'` fuses into the concrete peer tier of whichever `select'` set it joins
/// (via the `unify` fusion arms in check.rs).
fn infer_kernel_after(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::after";
    let mut local_errors: Vec<CheckError> = Vec::new();
    if args.len() != 3 {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::ArityMismatch {
                callee: OP.into(),
                expected: 3,
                got: args.len(),
            },
        });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        let o = fresh.fresh();
        let ty = TypeExpr::Parametric {
            head: "wat::kernel::Timer'".into(),
            args: vec![o],
        };
        return CheckResult::partial_with(ty, local_errors);
    }

    // arg 0: peer-kind — infer; must conform to :wat::program::PeerKind.
    let peer_kind_ty_opt = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    if let Some(peer_kind_ty) = &peer_kind_ty_opt {
        let expected_kind = TypeExpr::Path(":wat::program::PeerKind".into());
        if !assignable(peer_kind_ty, &expected_kind, subst, env) {
            local_errors.push(CheckError {
                span: args[0].span().clone(),
                kind: CheckErrorKind::TypeMismatch {
                    callee: OP.into(),
                    param: "peer-kind".into(),
                    expected: ":wat::program::PeerKind".into(),
                    got: format_type(peer_kind_ty),
                },
            });
        }
    }

    // arg 1: duration — infer; check it conforms to :wat::time::Duration.
    let dur_ty_opt = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    if let Some(dur_ty) = &dur_ty_opt {
        let expected_dur = TypeExpr::Path(":wat::time::Duration".into());
        if !assignable(dur_ty, &expected_dur, subst, env) {
            local_errors.push(CheckError {
                span: args[1].span().clone(),
                kind: CheckErrorKind::TypeMismatch {
                    callee: OP.into(),
                    param: "duration".into(),
                    expected: ":wat::time::Duration".into(),
                    got: format_type(dur_ty),
                },
            });
        }
    }

    // arg 2: msg — infer its type; that becomes O.
    let msg_ty = infer(&args[2], env, locals, fresh, subst)
        .drain_errors_into(&mut local_errors)
        .unwrap_or_else(|| fresh.fresh());

    // Return Timer'<O> — the tier-open timer type that fuses into the concrete
    // peer tier of the select' set it joins (via unify fusion arms in check.rs).
    let timer_ty = TypeExpr::Parametric {
        head: "wat::kernel::Timer'".into(),
        args: vec![msg_ty],
    };
    if local_errors.is_empty() {
        CheckResult::ok(timer_ty)
    } else {
        CheckResult::partial_with(timer_ty, local_errors)
    }
}

// PARTITION — CLAUSE vs INTRINSIC: `infer_send_prime` is INTRINSIC (projective).
// I flows from the peer's Parametric type param into the payload argument position.
/// Type-check `(:wat::kernel::send' peer payload)` — Stone 4.6a-ii.
///
/// Two positional args: `args[0]` peer, `args[1]` payload of type I.
/// Result: `:wat::core::nil`.
fn infer_send_prime(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::send'";
    let mut local_errors: Vec<CheckError> = Vec::new();
    if args.len() != 2 {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::ArityMismatch {
                callee: OP.into(),
                expected: 2,
                got: args.len(),
            },
        });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        return CheckResult::partial_with(TypeExpr::Path(":wat::core::nil".into()), local_errors);
    }

    let (i_ty, _o_ty) =
        match project_peer_io(args, head_span, OP, env, locals, fresh, subst, &mut local_errors) {
            Ok(pair) => pair,
            Err(()) => {
                // Still infer args[1] for nested error coverage.
                let _ = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
                return CheckResult::partial_with(TypeExpr::Path(":wat::core::nil".into()), local_errors);
            }
        };

    // args[1]: payload — must unify with I.
    let payload_ty =
        match infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
            Some(t) => t,
            None => {
                return CheckResult::partial_with(
                    TypeExpr::Path(":wat::core::nil".into()),
                    local_errors,
                );
            }
        };
    if let Err(_) = unify(&payload_ty, &i_ty, subst, env.types()) {
        local_errors.push(CheckError {
            span: args[1].span().clone(),
            kind: CheckErrorKind::TypeMismatch {
                callee: OP.into(),
                param: "payload".into(),
                expected: format_type(&apply_subst(&i_ty, subst)),
                got: format_type(&apply_subst(&payload_ty, subst)),
            },
        });
    }

    let ret = TypeExpr::Path(":wat::core::nil".into());
    if local_errors.is_empty() {
        CheckResult::ok(ret)
    } else {
        CheckResult::partial_with(ret, local_errors)
    }
}

// PARTITION — CLAUSE vs INTRINSIC: `infer_recv_prime` is INTRINSIC (projective).
// O flows from the peer's Parametric type param into the return type.
/// Type-check `(:wat::kernel::recv' peer)` — Stone 4.6a-ii / arc 258.5b.
///
/// One positional arg: `args[0]` peer → returns O (the peer's output type).
///
/// The `-> :T` ascription (3-arg form) is KILLED (arc 258.5b). `recv'` is 1-arg only.
/// `-> :T` is a function-return annotation — it is illegal in any other position.
/// The type flows from the consumer (258.5a: connect'/recv' unify) or the self-describing
/// EDN wire (post-234.7: tagged records/structs/enums + typed scalars decoded via sym.types()).
fn infer_recv_prime(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::recv'";
    let mut local_errors: Vec<CheckError> = Vec::new();

    // Arc 258.5b — `-> :T` on recv' is illegal; reject it with a clear error.
    // The arrow is a function-return annotation only. Detect the 3-arg form and any
    // multi-arg form that looks like an ascription attempt, and surface a targeted error.
    if args.len() >= 2 {
        let maybe_arrow = matches!(&args[1], WatAST::Symbol(s, _) if s.as_str() == "->");
        let reason = if maybe_arrow {
            "`-> :T` is a function-return annotation only — it is illegal on recv'. \
             The type flows from the consumer (e.g. connect') or the self-describing EDN wire. \
             Use (recv' peer) with no ascription."
                .into()
        } else {
            format!(
                "recv' takes exactly one argument (peer); got {}. \
                 Use (recv' peer) with no ascription.",
                args.len()
            )
        };
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::MalformedForm {
                head: OP.into(),
                reason,
                remedies: vec![],
            },
        });
        // Still infer all args for error coverage.
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        let t = fresh.fresh();
        return CheckResult::partial_with(t, local_errors);
    }

    if args.len() != 1 {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::ArityMismatch {
                callee: OP.into(),
                expected: 1,
                got: args.len(),
            },
        });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        let t = fresh.fresh();
        return CheckResult::partial_with(t, local_errors);
    }

    match project_peer_io(args, head_span, OP, env, locals, fresh, subst, &mut local_errors) {
        Ok((_i_ty, o_ty)) => {
            let ret = apply_subst(&o_ty, subst);
            if local_errors.is_empty() {
                CheckResult::ok(ret)
            } else {
                CheckResult::partial_with(ret, local_errors)
            }
        }
        Err(()) => {
            let t = fresh.fresh();
            CheckResult::partial_with(t, local_errors)
        }
    }
}

// PARTITION — CLAUSE vs INTRINSIC: `infer_close_prime` is INTRINSIC (∀-parametric).
// The peer arg is Thread'<∀I,∀O> or Process'<∀I,∀O>; a defclause cannot enumerate
// all (I,O) instantiations — the same infinite-open-set argument as get/recv'.
/// Type-check `(:wat::kernel::close' peer)` — Stone 4.6a-ii.
///
/// One positional arg: `args[0]` peer (Thread'<I,O> or Process'<I,O>).
/// Result: `nil` for Thread'; `i64` (exit code) for Process'.
fn infer_close_prime(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::close'";
    let mut local_errors: Vec<CheckError> = Vec::new();
    if args.len() != 1 {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::ArityMismatch {
                callee: OP.into(),
                expected: 1,
                got: args.len(),
            },
        });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        return CheckResult::partial_with(TypeExpr::Path(":wat::core::nil".into()), local_errors);
    }

    let peer_ty = match infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
        Some(t) => t,
        None => {
            return CheckResult::partial_with(TypeExpr::Path(":wat::core::nil".into()), local_errors);
        }
    };
    let peer_surface = apply_subst(&peer_ty, subst);
    let peer_reduced = reduce(&peer_surface, subst, env.types());
    let ret = match &peer_reduced {
        TypeExpr::Parametric { head, args }
            if head == "wat::kernel::Thread'" && args.len() == 2 =>
        {
            TypeExpr::Path(":wat::core::nil".into())
        }
        TypeExpr::Parametric { head, args }
            if head == "wat::kernel::Process'" && args.len() == 2 =>
        {
            TypeExpr::Path(":wat::core::i64".into())
        }
        other => {
            local_errors.push(CheckError {
                span: args[0].span().clone(),
                kind: CheckErrorKind::TypeMismatch {
                    callee: OP.into(),
                    param: "peer".into(),
                    expected: "peer (Thread'<I,O> | Process'<I,O>)".into(),
                    got: format_type(other),
                },
            });
            TypeExpr::Path(":wat::core::nil".into())
        }
    };
    if local_errors.is_empty() {
        CheckResult::ok(ret)
    } else {
        CheckResult::partial_with(ret, local_errors)
    }
}

// PARTITION — CLAUSE vs INTRINSIC: `infer_select_prime` is INTRINSIC (projective).
// I,O flow from Vector<peer<I,O>>'s element peer type into the return ServiceEvent<I,O,A>.
// A clause cannot enumerate Vector<Thread'<∀I,∀O>> / Vector<Process'<∀I,∀O>> —
// the same infinite-open-set argument as get/recv'. Mixed tiers are already
// forbidden by Vector homogeneity at check; no bespoke rejection needed.
/// Type-check `(:wat::kernel::select' peers)` — Stone 4.6b / Stone 259 Lost-locus.
///
/// One positional arg: `args[0]` a `Vector<Thread'<I,O>>` or
/// `Vector<Process'<I,O>>`. Returns `ServiceEvent<I,O,A>`.
///
/// select' has no self-peer / lineage channel, so `A` (the admin receive type) is a
/// fresh unconstrained tyvar — the :Admin variant can never fire from select'.
///
/// On success: `TypeExpr::Parametric { "wat::spawn::ServiceEvent", [I, O, A] }`.
/// On failure (non-peer element type): TypeMismatch with
/// "Vector of Thread'<I,O> | Process'<I,O> peers".
fn infer_select_prime(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::select'";
    let mut local_errors: Vec<CheckError> = Vec::new();

    // Arc 209 Stone C0b.2e-i-c: select' is 1-arg-only.
    // The 3-arg service multiplexer is poll' — use (poll' self listener clients).
    if args.len() != 1 {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::MalformedForm {
                head: OP.into(),
                reason: format!(
                    "select' takes one peer vector (fan-in); got {} args. \
                     The 3-arg service multiplexer is poll'.",
                    args.len()
                ),
                remedies: vec![],
            },
        });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        let fb = TypeExpr::Parametric {
            head: "wat::spawn::ServiceEvent".into(),
            args: vec![fresh.fresh(), fresh.fresh(), fresh.fresh()],
        };
        return CheckResult::partial_with(fb, local_errors);
    }

    // Infer the argument — must be Vector<peer<I,O>>.
    let vec_ty = match infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
        Some(t) => t,
        None => {
            let fb = TypeExpr::Parametric {
                head: "wat::spawn::ServiceEvent".into(),
                args: vec![fresh.fresh(), fresh.fresh(), fresh.fresh()],
            };
            return CheckResult::partial_with(fb, local_errors);
        }
    };
    let vec_surface = apply_subst(&vec_ty, subst);
    let vec_reduced = reduce(&vec_surface, subst, env.types());

    // Match Vector<elem>.
    let elem_ty = match &vec_reduced {
        TypeExpr::Parametric { head, args: targs }
            if head == "wat::core::Vector" && targs.len() == 1 =>
        {
            targs[0].clone()
        }
        other => {
            local_errors.push(CheckError {
                span: args[0].span().clone(),
                kind: CheckErrorKind::TypeMismatch {
                    callee: OP.into(),
                    param: "peers".into(),
                    expected: "Vector of Thread'<I,O> | Process'<I,O> peers".into(),
                    got: format_type(other),
                },
            });
            let fb = TypeExpr::Parametric {
                head: "wat::spawn::ServiceEvent".into(),
                args: vec![fresh.fresh(), fresh.fresh(), fresh.fresh()],
            };
            return CheckResult::partial_with(fb, local_errors);
        }
    };

    // Reduce the element type to a peer Parametric.
    let elem_surface = apply_subst(&elem_ty, subst);
    let elem_reduced = reduce(&elem_surface, subst, env.types());
    let (i_ty, o_ty) = match &elem_reduced {
        TypeExpr::Parametric { head, args: targs }
            if (head == "wat::kernel::Thread'" || head == "wat::kernel::Process'")
                && targs.len() == 2 =>
        {
            // I = args[0] (input to spawned fn from parent); O = args[1] (output back to parent).
            (targs[0].clone(), targs[1].clone())
        }
        // arc 292 — lone Timer'<O> element (mixed sets are absorbed to the concrete peer
        // tier via unify fusion; this arm handles the all-timers case). Timer has no input.
        TypeExpr::Parametric { head, args: targs }
            if head == "wat::kernel::Timer'" && targs.len() == 1 =>
        {
            (TypeExpr::Path(":wat::core::nil".into()), targs[0].clone())  // (I=nil, O)
        }
        other => {
            local_errors.push(CheckError {
                span: args[0].span().clone(),
                kind: CheckErrorKind::TypeMismatch {
                    callee: OP.into(),
                    param: "peers".into(),
                    expected: "Vector of Thread'<I,O> | Process'<I,O> peers".into(),
                    got: format_type(other),
                },
            });
            let fb = TypeExpr::Parametric {
                head: "wat::spawn::ServiceEvent".into(),
                args: vec![fresh.fresh(), fresh.fresh(), fresh.fresh()],
            };
            return CheckResult::partial_with(fb, local_errors);
        }
    };

    let i_resolved = apply_subst(&i_ty, subst);
    let o_resolved = apply_subst(&o_ty, subst);
    // select' has no self-peer / lineage channel — :Admin can never fire.
    // Use a fresh unconstrained tyvar for A so the arity matches ServiceEvent<I,O,A>.
    let a_fresh = fresh.fresh();
    let ret = TypeExpr::Parametric {
        head: "wat::spawn::ServiceEvent".into(),
        args: vec![i_resolved, o_resolved, a_fresh],
    };
    if local_errors.is_empty() {
        CheckResult::ok(ret)
    } else {
        CheckResult::partial_with(ret, local_errors)
    }
}

/// Arc 209 Stone C0b.1b / C0b.2e-i-c — `(:wat::kernel::poll' self-peer listener peers)` → `ServiceEvent<I,O,A>`.
///
/// 3-arg service-multiplexer form:
///   args[0] = self-peer (`Peer'<S,R>` — the owner link; R = admin receive type A).
///   args[1] = listener (`Listener'<S,R>` — inferred permissively, not further constrained).
///   args[2] = peers (`Vector<Peer'<I,O>>` — the connected client peers).
///
/// Arc 291 3a-i: returns `Parametric { "wat::spawn::ServiceEvent", [I, O, A] }`.
///   I, O flow from the peers vector element type.
///   A = the self-peer's receive type (args[0]: Peer'<_,A>) — the admin channel receive type.
fn infer_poll_prime(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    const OP: &str = ":wat::kernel::poll'";
    let mut local_errors: Vec<CheckError> = Vec::new();

    // args[0]: self-peer — infer and extract the receive type A (targs[1] of Peer'<S,A>).
    // A is the type the service receives from the owner over the lineage channel (admin ops).
    let a_ty: TypeExpr = {
        let self_peer_ty = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        match self_peer_ty {
            Some(ty) => {
                let surface = apply_subst(&ty, subst);
                let reduced = reduce(&surface, subst, env.types());
                match &reduced {
                    TypeExpr::Parametric { head, args: targs }
                        if head == "wat::kernel::Peer'" && targs.len() == 2 =>
                    {
                        // Peer'<S, R>: targs[1] = R = what the service receives from the owner.
                        targs[1].clone()
                    }
                    _ => {
                        // Self-peer type unknown or not yet resolved — use a fresh tyvar.
                        fresh.fresh()
                    }
                }
            }
            None => fresh.fresh(),
        }
    };

    // args[1]: listener — infer for error coverage; type not further constrained here.
    let _ = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);

    // args[2]: peers — must be Vector<Peer'<I,O>>.
    let vec_ty = match infer(&args[2], env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
        Some(t) => t,
        None => {
            let fb = TypeExpr::Parametric {
                head: "wat::spawn::ServiceEvent".into(),
                args: vec![fresh.fresh(), fresh.fresh(), fresh.fresh()],
            };
            return if local_errors.is_empty() {
                CheckResult::ok(fb)
            } else {
                CheckResult::partial_with(fb, local_errors)
            };
        }
    };
    let vec_surface = apply_subst(&vec_ty, subst);
    let vec_reduced = reduce(&vec_surface, subst, env.types());

    // Match Vector<elem>.
    let elem_ty = match &vec_reduced {
        TypeExpr::Parametric { head, args: targs }
            if head == "wat::core::Vector" && targs.len() == 1 =>
        {
            targs[0].clone()
        }
        other => {
            local_errors.push(CheckError {
                span: args[2].span().clone(),
                kind: CheckErrorKind::TypeMismatch {
                    callee: OP.into(),
                    param: "peers".into(),
                    expected: "Vector<Peer'<I,O>> (connected client peers)".into(),
                    got: format_type(other),
                },
            });
            let fb = TypeExpr::Parametric {
                head: "wat::spawn::ServiceEvent".into(),
                args: vec![fresh.fresh(), fresh.fresh(), fresh.fresh()],
            };
            return CheckResult::partial_with(fb, local_errors);
        }
    };

    // Reduce the element type — accept Peer'<I,O>.
    let elem_surface = apply_subst(&elem_ty, subst);
    let elem_reduced = reduce(&elem_surface, subst, env.types());
    let (i_ty, o_ty) = match &elem_reduced {
        TypeExpr::Parametric { head, args: targs }
            if head == "wat::kernel::Peer'" && targs.len() == 2 =>
        {
            (targs[0].clone(), targs[1].clone())
        }
        other => {
            local_errors.push(CheckError {
                span: args[2].span().clone(),
                kind: CheckErrorKind::TypeMismatch {
                    callee: OP.into(),
                    param: "peers element".into(),
                    expected: "Peer'<I,O>".into(),
                    got: format_type(other),
                },
            });
            let fb = TypeExpr::Parametric {
                head: "wat::spawn::ServiceEvent".into(),
                args: vec![fresh.fresh(), fresh.fresh(), fresh.fresh()],
            };
            return CheckResult::partial_with(fb, local_errors);
        }
    };

    let i_resolved = apply_subst(&i_ty, subst);
    let o_resolved = apply_subst(&o_ty, subst);
    let a_resolved = apply_subst(&a_ty, subst);
    let ret = TypeExpr::Parametric {
        head: "wat::spawn::ServiceEvent".into(),
        args: vec![i_resolved, o_resolved, a_resolved],
    };
    if local_errors.is_empty() {
        CheckResult::ok(ret)
    } else {
        CheckResult::partial_with(ret, local_errors)
    }
}

/// Process one binding — single-typed or destructure. Infers the RHS
/// in `rhs_scope` and adds the binding(s) to `out_scope`.
#[allow(clippy::too_many_arguments)]
fn process_let_binding(
    pair: &WatAST,
    env: &CheckEnv,
    rhs_scope: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
    form: &str,
) -> CheckResult<HashMap<String, TypeExpr>> {
    let mut new_bindings: HashMap<String, TypeExpr> = HashMap::new();
    let mut binding_errors: Vec<CheckError> = Vec::new();
    let kv = match pair {
        WatAST::List(items, _) if items.len() == 2 => items,
        _ => return CheckResult::ok(new_bindings), // runtime parser surfaces the shape error
    };

    // Arc 159 — canonical new shape: `(name rhs)` where `name` is a
    // bare Symbol. Type is inferred from `rhs`; no annotation needed
    // (per arc 145 lesson). Walker dependency settled in arc 158a
    // (pair-deadlock walker pattern-matches RHS for channel-related
    // shapes). This branch MUST come before the binder-as-List logic so
    // the destructure path is not accidentally reached for new-shape
    // bindings.
    if let WatAST::Symbol(ident, _) = &kv[0] {
        let name = crate::scope::resolution::env_key(ident).into_owned();
        let rhs = &kv[1];
        let rhs_ty = infer(rhs, env, rhs_scope, fresh, subst).drain_errors_into(&mut binding_errors);
        if let Some(ty) = rhs_ty {
            new_bindings.insert(name, ty);
        }
        return if binding_errors.is_empty() {
            CheckResult::ok(new_bindings)
        } else {
            CheckResult::partial_with(new_bindings, binding_errors)
        };
    }

    // Arc 168 — Vector binder (destructure post-flat-shape):
    // `[a b c] rhs`. Each element must be a bare symbol; RHS must
    // unify with a tuple of fresh vars matching the arity.
    if let WatAST::Vector(inner, _) = &kv[0] {
        let mut names = Vec::with_capacity(inner.len());
        for item in inner {
            match item {
                WatAST::Symbol(ident, _) => names.push(crate::scope::resolution::env_key(ident).into_owned()),
                _ => return CheckResult::ok(new_bindings),
            }
        }
        if names.is_empty() {
            return CheckResult::ok(new_bindings);
        }
        let rhs = &kv[1];
        let elem_vars: Vec<TypeExpr> = (0..names.len()).map(|_| fresh.fresh()).collect();
        let tuple_ty = TypeExpr::Tuple(elem_vars.clone());
        let rhs_ty = infer(rhs, env, rhs_scope, fresh, subst).drain_errors_into(&mut binding_errors);
        if let Some(rhs_ty) = rhs_ty {
            if unify(&rhs_ty, &tuple_ty, subst, env.types()).is_err() {
                binding_errors.push(CheckError { span: rhs.span().clone(), kind: CheckErrorKind::TypeMismatch {
                    callee: form.into(),
                    param: format!("destructure ({})", names.join(" ")),
                    expected: format_type(&apply_subst(&tuple_ty, subst)),
                    got: format_type(&apply_subst(&rhs_ty, subst))
                } });
            }
        }
        for (name, ev) in names.into_iter().zip(elem_vars.into_iter()) {
            new_bindings.insert(name, apply_subst(&ev, subst));
        }
        return if binding_errors.is_empty() {
            CheckResult::ok(new_bindings)
        } else {
            CheckResult::partial_with(new_bindings, binding_errors)
        };
    }

    // Arc 257.2 — Map binder: keys-destructure ({:keys [f1 f2 ...]}) or
    // hash-destructure ({var :field ...}). classify_map_destructure is the
    // ONE authoritative helper (ast.rs).
    if let WatAST::Map(pairs, map_span) = &kv[0] {
        let md = WatAST::classify_map_destructure(pairs);
        if let Some(m) = md {
            match m.kind {
                crate::ast::MapDestructureKind::Hash => {
                    // Hash-destructure check path (arc 234 Stone 234.4 / arc 257.2).
                    // Per D4: each binding var receives a fresh type variable.
                    let rhs = &kv[1];
                    let _ = infer(rhs, env, rhs_scope, fresh, subst).drain_errors_into(&mut binding_errors);
                    for (ident, _, _) in &m.bindings {
                        let var_name = crate::scope::resolution::env_key(ident).into_owned();
                        new_bindings.insert(var_name, fresh.fresh());
                    }
                    return if binding_errors.is_empty() {
                        CheckResult::ok(new_bindings)
                    } else {
                        CheckResult::partial_with(new_bindings, binding_errors)
                    };
                }
                crate::ast::MapDestructureKind::Keys => {
                    // Keys-destructure check path (arc 169 / arc 257.2).
                    // Same struct-field lookup as the old struct-destructure binder.
                    let span = map_span;
                    let field_names: Vec<String> = m.bindings
                        .iter()
                        .map(|(ident, _, _)| ident.as_str().to_owned())
                        .collect();
                    if field_names.is_empty() {
                        return CheckResult::ok(new_bindings);
                    }
                    let rhs = &kv[1];
                    let rhs_ty = infer(rhs, env, rhs_scope, fresh, subst).drain_errors_into(&mut binding_errors);
                    let rhs_ty = match rhs_ty {
                        Some(t) => apply_subst(&t, subst),
                        None => return CheckResult::errs(binding_errors),
                    };
                    // The rhs must be a struct type — TypeExpr::Path naming a
                    // registered StructDef. Parametric struct instances flow
                    // through Path uniformly (the struct registry is keyed on
                    // the bare name; type parameters are resolved at use site).
                    let struct_name = match &rhs_ty {
                        TypeExpr::Path(n) => n.clone(),
                        // Parametric structs: head is the struct's name.
                        TypeExpr::Parametric { head, .. } => {
                            if head.starts_with(':') {
                                head.clone()
                            } else {
                                format!(":{}", head)
                            }
                        }
                        other => {
                            binding_errors.push(CheckError { span: rhs.span().clone(), kind: CheckErrorKind::TypeMismatch {
                                callee: form.into(),
                                param: format!("struct-destructure ({})", field_names.join(" ")),
                                expected: "a struct type".into(),
                                got: format_type(other)
                            } });
                            return CheckResult::errs(binding_errors);
                        }
                    };
                    let struct_def = match env.types().get(&struct_name) {
                        // Arc 293.2b — struct-destructure requires Aggregate with kind==Struct.
                        Some(crate::types::TypeDef::Aggregate(a)) if a.holder == crate::types::Holder::Struct => a.clone(),
                        _ => {
                            binding_errors.push(CheckError { span: rhs.span().clone(), kind: CheckErrorKind::TypeMismatch {
                                callee: form.into(),
                                param: format!("struct-destructure ({})", field_names.join(" ")),
                                expected: "a struct type".into(),
                                got: format_type(&rhs_ty)
                            } });
                            return CheckResult::errs(binding_errors);
                        }
                    };
                    // Look up each requested field; emit MalformedForm naming
                    // the offending field + listing the struct's actual fields
                    // when a name doesn't match (substrate-as-teacher).
                    for fname in &field_names {
                        match struct_def.fields.iter().find(|(n, _)| n == fname) {
                            Some((_, fty)) => {
                                new_bindings.insert(fname.clone(), apply_subst(fty, subst));
                            }
                            None => {
                                let declared = struct_def
                                    .fields
                                    .iter()
                                    .map(|(n, _)| n.as_str())
                                    .collect::<Vec<_>>()
                                    .join(", ");
                                binding_errors.push(CheckError { span: span.clone(), kind: CheckErrorKind::MalformedForm {
                                    head: form.into(),
                                    reason: format!(
                                        "struct-destructure: field {:?} is not declared on struct {} (declared fields: {})",
                                        fname, struct_def.name, declared
                                    ),
                                    remedies: vec![],
                                } });
                            }
                        }
                    }
                    return if binding_errors.is_empty() {
                        CheckResult::ok(new_bindings)
                    } else {
                        CheckResult::partial_with(new_bindings, binding_errors)
                    };
                }
            }
        }
    }

    // Anything else — malformed binder shape. Arc 168 slice 3
    // retired the legacy typed-single `(name :T)` and legacy List
    // destructure binder arms.
    //
    // Arc 214 P2 note: `{}` in expression position now parses as a
    // `WatAST::List` (the desugared HashMap call) rather than an
    // error. If that List lands in a let binder position (e.g.
    // `[{} p]`), it is structurally invalid as a binder. Emit a
    // MalformedForm here so the type-checker surfaces a diagnostic
    // at startup rather than silently accepting and letting the
    // runtime catch it.
    let binder = &kv[0];
    binding_errors.push(CheckError { span: binder.span().clone(), kind: CheckErrorKind::MalformedForm {
        head: form.into(),
        reason: format!(
            "let binder must be a bare symbol (single binding), a vector of symbols (tuple destructure), or a bare-symbol brace-form (struct destructure); got a {} in binder position",
            binder.variant_name()
        ),
        remedies: vec![],
    } });
    CheckResult::errs(binding_errors)
}

/// Type-check `(:wat::core::HashSet :T x1 x2 ...)`. First arg is a
/// type keyword; remaining args are elements, each unifying with T.
/// Explicit typing required (matches the vec/list / make-queue
/// resource-constructor discipline — shape never depends on context).
fn infer_hashset_constructor(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    if args.is_empty() {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: ":wat::core::HashSet".into(),
            expected: 1,
            got: 0
        } });
        let ty = TypeExpr::Parametric {
            head: "wat::core::HashSet".into(),
            args: vec![fresh.fresh()],
        };
        // HARVEST (236.2): existing diagnostic; partial — return HashSet placeholder.
        return CheckResult::partial_with(ty, local_errors);
    }
    let t_ty = match &args[0] {
        WatAST::Keyword(k, _) => {
            // Arc 215 stone 1 — :wat::type::Infer means "infer T from
            // the elements." Route to a fresh type variable; the
            // unification loop below concretizes it from the first element.
            if k == crate::types::INFER_TYPE_PATH {
                fresh.fresh()
            } else {
                match crate::types::parse_type_expr(k) {
                    Ok(t) => t,
                    Err(_) => {
                        local_errors.push(CheckError { span: args[0].span().clone(), kind: CheckErrorKind::MalformedForm {
                            head: ":wat::core::HashSet".into(),
                            reason: format!("first argument {} is not a valid type keyword", k),
                            remedies: vec![],
                        } });
                        fresh.fresh()
                    }
                }
            }
        }
        _ => {
            local_errors.push(CheckError { span: args[0].span().clone(), kind: CheckErrorKind::MalformedForm {
                head: ":wat::core::HashSet".into(),
                reason: "first argument must be a type keyword (e.g., :i64)".into(),
                remedies: vec![],
            } });
            fresh.fresh()
        }
    };
    for (i, arg) in args[1..].iter().enumerate() {
        if let Some(ty) = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
            if unify(&ty, &t_ty, subst, env.types()).is_err() {
                local_errors.push(CheckError { span: arg.span().clone(), kind: CheckErrorKind::TypeMismatch {
                    callee: ":wat::core::HashSet".into(),
                    param: format!("element #{}", i + 1),
                    expected: format_type(&apply_subst(&t_ty, subst)),
                    got: format_type(&apply_subst(&ty, subst))
                } });
            }
        }
    }
    let ty = TypeExpr::Parametric {
        head: "wat::core::HashSet".into(),
        args: vec![apply_subst(&t_ty, subst)],
    };
    if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) }
}

/// Arc 050 — polymorphic comparison/equality inference.
///
/// Check-side signature inference for the polymorphic comparison
/// family (`:wat::core::{=,not=,<,>,<=,>=}`). Same-type or
/// subtype-related required per THE DECISION. Always returns `:bool`.
///
/// arc 237 Stone 237.8a — THE DECISION (`feedback_no_implicit_coercion`):
/// cross-numeric path DELETED. `(< 1 2.0)` → TypeMismatch at check.
/// Numeric comparison is now same-type-only: (i64, i64) succeeds via
/// unify; (f64, f64) succeeds via unify; (i64, f64) fails unify AND
/// neither is a subtype of the other → TypeMismatch. Callers
/// homogenize explicitly before comparing.
///
/// The runtime path (`eval_eq` / `eval_compare` / `eval_not_eq`
/// over `values_equal` / `values_compare`) is the defense-in-depth
/// companion; check-time tightening is the primary gate.
///
/// Renamed from `infer_polymorphic_compare` in arc 148 slice 5
/// to drop the polymorphic-handler anti-pattern framing. The
/// function IS the check-side `:wat::core::<` family inference;
/// nothing about it is anti-pattern. Per-Type comparison leaves
/// retired in the same slice.
// PARTITION — RELATIONAL flavor of the intrinsic dispatch: `unify(a, b)` ties
// the two args' types ∀T, which a monomorphic clause cannot express. See `docs/DISPATCH.md`.
fn infer_equality(
    op: &str,
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    let bool_ty = TypeExpr::Path(":wat::core::bool".into());
    if args.len() != 2 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: op.into(),
            expected: 2,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        // HARVEST (236.2): existing diagnostic; comparison always returns bool.
        return CheckResult::partial_with(bool_ty, local_errors);
    }
    let a_ty = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    let b_ty = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    if let (Some(a), Some(b)) = (a_ty, b_ty) {
        let a_resolved = apply_subst(&a, subst);
        let b_resolved = apply_subst(&b, subst);
        // arc 237 Stone 237.8a — THE DECISION: cross-numeric path DELETED.
        // (i64, f64) and (f64, i64) now fall through to the same-type-or-
        // subtype check below; they fail unify and neither is a subtype of
        // the other → TypeMismatch. Callers homogenize explicitly.
        //
        // Same-type or subtype-related required.
        // `=` is type-strict at runtime (different variants → false), but
        // type-COMPATIBLE at check time: two types that share a common ancestor
        // via the `typesub` hierarchy may be compared — the result may be false
        // but the comparison is well-formed (Stone S-C.3: base-vs-holonic record
        // cross-flavor comparison is meaningful, result always false).
        // Arc 258 cascade — two specifically-typed records (e.g. :my::Pt and
        // :my::HPt) both share :wat::core::Record as a common ancestor; comparing them
        // is type-compatible (always evaluates to false at runtime, which is correct
        // and meaningful). Check: unify OR one is a subtype of the other OR both
        // are record subtypes (share the :wat::core::Record common ancestor).
        let types_compatible = if unify(&a_resolved, &b_resolved, subst, env.types()).is_ok() {
            true
        } else if let (TypeExpr::Path(ap), TypeExpr::Path(bp)) = (&a_resolved, &b_resolved) {
            crate::types::is_subtype(ap, bp, env.types())
                || crate::types::is_subtype(bp, ap, env.types())
                || (crate::types::is_subtype(ap, ":wat::core::Record", env.types())
                    && crate::types::is_subtype(bp, ":wat::core::Record", env.types()))
        } else {
            false
        };
        if !types_compatible {
            local_errors.push(CheckError { span: args[1].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: op.into(),
                param: "#2".into(),
                expected: format_type(&apply_subst(&a_resolved, subst)),
                got: format_type(&apply_subst(&b_resolved, subst))
            } });
        }
    }
    if local_errors.is_empty() { CheckResult::ok(bool_ty) } else { CheckResult::partial_with(bool_ty, local_errors) }
}

// Stone 237.8b — HARD CUT: `infer_arithmetic` and `is_numeric` deleted.
// `:wat::core::+`/`-`/`*`/`/` now route through wat defclauses (registered
// in env.defclause_registrations). The defclause call-site checker
// (infer_defclause, line ~5262) handles arity + type-dispatch. No custom
// Rust handler needed.
//
// `infer_comparison`'s `<`/`>`/`<=`/`>=` arms also deleted (same stone);
// those ops routed through wat defclauses. `infer_comparison` renamed to
// `infer_equality` in Stone 237.8c (only `=`/`not=` remain as tenants).
//
// Stone 245.8 — `<`/`>`/`<=`/`>=` PROMOTED from defclauses to a relational
// intrinsic: `infer_ordering` (below). The ordering defclauses in wat/core.wat
// are retired; the runtime dispatch arms now route directly to `eval_compare`.

/// Check whether a (fully-substituted / reduced) TypeExpr belongs to the
/// orderable class: `i64`, `u8`, `f64`, `String`, `bool`, `keyword`,
/// `Instant`, `Duration`, and recursively `Vector<orderable>`,
/// `Tuple<orderable…>`, `Option<orderable>`, `Result<orderable, orderable>`.
///
/// Unresolved TypeVars are accepted (deferred — mirrors `infer_equality`'s
/// TypeVar policy; the runtime's `values_compare → None` is the eval-side
/// backstop).
///
/// NOT orderable: `HashMap`, `HashSet`, user enums / Records / Structs,
/// unit `()`, fn types, `HolonAST`, channels/handles.
fn is_type_orderable(ty: &TypeExpr, subst: &Subst) -> bool {
    let resolved = apply_subst(ty, subst);
    match &resolved {
        TypeExpr::Var(_) => true, // unresolved — defer to runtime
        TypeExpr::Path(p) => matches!(
            p.as_str(),
            ":wat::core::i64"
                | ":wat::core::u8"
                | ":wat::core::f64"
                | ":wat::core::String"
                | ":wat::core::bool"
                | ":wat::core::keyword"
                | ":wat::time::Instant"
                | ":wat::time::Duration"
                // Arc 148 slice 3 — algebra Vector (bit-exact i8 lex via values_compare).
                | ":wat::holon::Vector"
        ),
        TypeExpr::Parametric { head, args } => match head.as_str() {
            "wat::core::Vector" => args.first().is_none_or(|el| is_type_orderable(el, subst)),
            "wat::core::Option" => args.first().is_none_or(|el| is_type_orderable(el, subst)),
            "wat::core::Result" => {
                // Result<T, E> orderable iff both T and E are orderable
                args.first().is_none_or(|t| is_type_orderable(t, subst))
                    && args.get(1).is_none_or(|e| is_type_orderable(e, subst))
            }
            _ => false,
        },
        // Empty tuple = unit: NOT orderable. The vacuous-all rule would accept
        // it at check while the runtime engine refuses it — the check≡runtime
        // split Stone 245.8's scoring caught live. Ordering a one-inhabitant
        // type is meaningless; check mirrors the runtime's refusal.
        TypeExpr::Tuple(elems) => {
            !elems.is_empty() && elems.iter().all(|el| is_type_orderable(el, subst))
        }
        TypeExpr::Fn { .. } => false,
    }
}

// PARTITION — RELATIONAL flavor of the intrinsic dispatch (ordering sibling of `infer_equality`).
// `unify(a, b)` ties the two args' types ∀T (strict — no subtype-compatible path for ordering);
// then the unified type is gated against the orderable class. See `docs/DISPATCH.md`.
fn infer_ordering(
    op: &str,
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    let bool_ty = TypeExpr::Path(":wat::core::bool".into());
    if args.len() != 2 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: op.into(),
            expected: 2,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        return CheckResult::partial_with(bool_ty, local_errors);
    }
    let a_ty = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    let b_ty = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    if let (Some(a), Some(b)) = (a_ty, b_ty) {
        let a_resolved = apply_subst(&a, subst);
        let b_resolved = apply_subst(&b, subst);
        // Ordering is STRICT same-type — unlike equality there is NO subtype-compatible path.
        // Cross-type (i64 vs f64) must fail here: unify rejects it, producing TypeMismatch.
        // This is the principal doc: the error KIND changes from NoMatchingClause (old defclause
        // path) to TypeMismatch (unify failure) for cross-type ordering.
        if unify(&a_resolved, &b_resolved, subst, env.types()).is_err() {
            local_errors.push(CheckError { span: args[1].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: op.into(),
                param: "#2".into(),
                expected: format_type(&apply_subst(&a_resolved, subst)),
                got: format_type(&apply_subst(&b_resolved, subst))
            } });
        } else {
            // Types unified — now gate on the orderable class.
            let unified = apply_subst(&a_resolved, subst);
            if !is_type_orderable(&unified, subst) {
                local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::TypeMismatch {
                    callee: op.into(),
                    param: "#1".into(),
                    expected: "an orderable type (i64, u8, f64, String, bool, keyword, Instant, Duration, Vector<T>, Tuple<T…>, Option<T>, Result<T,E>)".into(),
                    got: format_type(&unified)
                } });
            }
        }
    }
    if local_errors.is_empty() { CheckResult::ok(bool_ty) } else { CheckResult::partial_with(bool_ty, local_errors) }
}

/// Arc 237 Stone S-C.3 — BASE record constructor inference.
///
/// `:wat::core::Record::of` takes two arguments:
///   #1  class-FQDN   — must be `:wat::core::keyword`
///   #2  struct-form  — must be a Vector literal `[...]` or `:wat::core::Vector` call;
///                      elements are type-checked independently; NO uniform-T unification
///                      (struct_form is Arc<Vec<Value>> by design — heterogeneous)
///
/// Returns `:wat::core::Record`.
///
/// The umbrella DESIGN (arc 234 line 19) specifies `struct_form: Arc<Vec<Value>>` which
/// is heterogeneous by construction. The original TypeScheme registration used
/// `Vector<T>` (uniform-T), creating an inconsistency with both the DESIGN intent and the
/// runtime's `eval_record_of` (which accepts any Vec without element-type enforcement).
/// This custom handler corrects that inconsistency.
///
/// Modeled after `infer_arithmetic` (arc 148 slice 4) — same custom-handler pattern.
fn infer_record_of(
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    const CALLEE: &str = ":wat::core::Record::of";
    // Arity check: exactly 2 args (class, struct_form).
    if args.len() != 2 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: CALLEE.into(),
            expected: 2,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        // HARVEST (236.2): existing diagnostic; partial — return Record placeholder.
        return CheckResult::partial_with(TypeExpr::Path(":wat::core::Record".into()), local_errors);
    }

    // Arg #1: class-FQDN — must infer to :wat::core::keyword.
    let class_ty = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    if let Some(ct) = class_ty {
        let keyword_ty = TypeExpr::Path(":wat::core::keyword".into());
        if unify(&ct, &keyword_ty, subst, env.types()).is_err() {
            local_errors.push(CheckError { span: args[0].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: CALLEE.into(),
                param: "#1".into(),
                expected: ":wat::core::keyword".into(),
                got: format_type(&apply_subst(&ct, subst))
            } });
        }
    }

    // Arg #2: struct-form — must be a Vector literal or :wat::core::Vector call.
    // Each element is type-checked independently; no uniform-T unification.
    match &args[1] {
        WatAST::Vector(elems, _) => {
            // `[e0 e1 ...]` vector literal — infer each element independently.
            for elem in elems.iter() {
                let _ = infer(elem, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
            }
        }
        WatAST::List(items, _) => {
            // Could be (:wat::core::Vector :T e0 e1 ...) or a call that returns a Vector.
            // Check if head is :wat::core::Vector keyword; if so, infer elements (skip
            // the type-arg at position 0). Otherwise fall through to generic infer.
            let is_vector_head = matches!(
                items.first(),
                Some(WatAST::Keyword(k, _)) if k == ":wat::core::Vector"
            );
            if is_vector_head && items.len() > 1 {
                // items[0] is :wat::core::Vector, items[1] is the type-arg — skip it.
                // items[2..] are the elements; infer each independently.
                for elem in items[2..].iter() {
                    let _ = infer(elem, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
                }
            } else {
                // A general expression in struct-form position (e.g., a variable bound
                // to a Vector). Infer it normally; no shape validation at check time.
                let _ = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
            }
        }
        _ => {
            // Not a recognized Vec shape. Infer and emit a shape error.
            let _ = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
            local_errors.push(CheckError { span: args[1].span().clone(), kind: CheckErrorKind::MalformedForm {
                head: CALLEE.into(),
                reason: "struct_form (arg #2) must be a Vector literal `[...]` \
                         or a :wat::core::Vector expression"
                    .into(),
                remedies: vec![],
            } });
        }
    }

    // The construction's type is the SPECIFIC record its class names — NOT the generic
    // :wat::core::Record. Arc 258: records were collapsed to :wat::core::Record because this returned the
    // root, which made the whole subtype hierarchy (register_subtype/is_subtype) unreachable —
    // no value could ever be typed as a specific record. The Record::def macro +
    // register_record_methods build arg[0] as `(:wat::core::keyword/from-string "user::MyEnv")`,
    // so the class FQDN is the static StringLit prefixed with ':'. If it names a recordtype,
    // the construction IS that record. (Falls back to :wat::core::Record for a non-static/non-record class.)
    let ty = record_of_specific_type(&args[0], env)
        .unwrap_or_else(|| TypeExpr::Path(":wat::core::Record".into()));
    if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) }
}

/// Recover the SPECIFIC record type a `Record::of` constructs, from its statically-known class
/// argument `(:wat::core::keyword/from-string "<fqdn-without-leading-colon>")`. Returns `None`
/// when the class is not a static, registered recordtype (caller falls back to `:wat::core::Record`).
///
/// Arc 293.R2.2 — after `parse_recordtype` was fixed to store the BARE name (`:t::R` not `:t::R<T>`),
/// the class string in the macro is `"t::R<T>"` but the TypeEnv key is `":t::R"`. Strip the type
/// params from the class string before lookup; reconstruct the parametric TypeExpr using the
/// AggregateDef's declared `type_params` so `Record::of` correctly infers `:r2::CR<T>` for generic
/// records (fixing the ReturnTypeMismatch for generic record ctors).
fn record_of_specific_type(class_arg: &WatAST, env: &CheckEnv) -> Option<TypeExpr> {
    let WatAST::List(items, _) = class_arg else { return None };
    if items.len() != 2 { return None; }
    let from_string = matches!(
        items.first(),
        Some(WatAST::Keyword(k, _)) if k == ":wat::core::keyword/from-string"
    );
    if !from_string { return None; }
    let WatAST::StringLit(s, _) = items.get(1)? else { return None };
    // Strip any type-params suffix (`<T>`, `<K,V>`) before the TypeEnv lookup.
    // Before the R2.2 parse_recordtype fix, the TypeEnv key carried the full `<T>`;
    // after the fix, the key is the bare name. The class string in the macro is still
    // derived from `keyword/to-string` of the original keyword (e.g., `"r2::CR<T>"`)
    // so we must strip here.
    let bare_str = s.split('<').next().unwrap_or(s.as_str());
    let class_name = format!(":{}", bare_str);
    // Arc 293.2b — record aggregates (kind != Struct) are the records.
    let agg = match env.types().get(&class_name) {
        Some(crate::types::TypeDef::Aggregate(a)) if a.holder != crate::types::Holder::Struct => a,
        _ => return None,
    };
    // For non-generic records: return the bare path (existing behaviour).
    // For generic records: reconstruct the parametric type using the declared type_params
    // so the checker's return-type unification works for `:r2::CR<T>`.
    if agg.type_params.is_empty() {
        Some(TypeExpr::Path(class_name))
    } else {
        Some(TypeExpr::Parametric {
            head: bare_str.to_string(),
            args: agg.type_params.iter()
                .map(|p| TypeExpr::Path(format!(":{}", p)))
                .collect(),
        })
    }
}

/// Arc 294.c.2a — type inference for `:wat::core::aggregate-new`.
///
/// `aggregate-new` is the ONE holder-dispatched constructor. It takes a direct
/// keyword literal as args[0] (e.g. `:test::an::HR`) and zero or more field
/// values. Returns the SPECIFIC aggregate type so downstream checks (cosine,
/// accessor param unification) see the concrete type instead of a TypeVar.
///
/// Unlike `record_of_specific_type` (which parses `(:wat::core::keyword/from-string "...")`)
/// the class here is a bare keyword literal — no sub-form to unwrap.
fn infer_aggregate_new_check(
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    const CALLEE: &str = ":wat::core::aggregate-new";

    if args.is_empty() {
        local_errors.push(CheckError {
            span: head_span.clone(),
            kind: CheckErrorKind::ArityMismatch { callee: CALLEE.into(), expected: 1, got: 0 },
        });
        return CheckResult::errs(local_errors);
    }

    // Infer all field args (args[1..]) for side effects (type propagation, error harvest).
    for arg in args.iter().skip(1) {
        let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    }

    // Extract specific type from args[0]: expected to be a direct keyword literal.
    //
    // For the macro-expanded case, the keyword may include a type-params suffix
    // (e.g. `:wat::kernel::Thread<I,O>`) because ~fqdn in the macro template is
    // the raw source keyword. TypeEnv stores keys WITHOUT the suffix (":wat::kernel::Thread"),
    // so strip `<…>` before lookup.
    //
    // We look up the CTOR SCHEME from env rather than reconstructing the type from
    // the TypeEnv's type_params. The scheme's ret field already has the correct
    // parametric form — Rust-registered structs use Path("I") (no colon) via
    // parametric_decl_type; WAT-parsed macro-generated types use Path(":I") via
    // parse_type_inner. Reconstructing from type_params would produce the wrong
    // form for one of these two sources, causing unify to fail even though both
    // format_type displays appear identical (format_type_inner strips the colon).
    let ty = if let WatAST::Keyword(k, _) = &args[0] {
        let bare_k: &str = if let Some(pos) = k.find('<') { &k[..pos] } else { k.as_str() };
        // Look up the ctor scheme — its ret IS the specific type in the correct form.
        if let Some(scheme) = env.get(bare_k) {
            scheme.ret.clone()
        } else {
            // No scheme registered yet (will error at resolve time); return the bare path.
            TypeExpr::Path(bare_k.to_string())
        }
    } else {
        // Non-static class arg — infer for side effects; fall back to fresh TypeVar.
        let _ = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        fresh.fresh()
    };

    if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) }
}

/// Arc 237 Stone S-C.3 — HOLONIC record constructor inference.
///
/// `:wat::holon::Record::of` takes three arguments:
///   #1  class-FQDN   — must be `:wat::core::keyword`
///   #2  struct-form  — must be a Vector literal `[...]` or `:wat::core::Vector` call;
///                      elements are type-checked independently; NO uniform-T unification
///   #3  holon-form   — must be `:wat::holon::HolonAST`
///
/// Returns `:wat::holon::Record`.
fn infer_holon_record_of(
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    const CALLEE: &str = ":wat::holon::Record::of";
    // Arity check: exactly 3 args (class, struct_form, holon_form).
    if args.len() != 3 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: CALLEE.into(),
            expected: 3,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        return CheckResult::partial_with(TypeExpr::Path(":wat::holon::Record".into()), local_errors);
    }

    // Arg #1: class-FQDN — must infer to :wat::core::keyword.
    let class_ty = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    if let Some(ct) = class_ty {
        let keyword_ty = TypeExpr::Path(":wat::core::keyword".into());
        if unify(&ct, &keyword_ty, subst, env.types()).is_err() {
            local_errors.push(CheckError { span: args[0].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: CALLEE.into(),
                param: "#1".into(),
                expected: ":wat::core::keyword".into(),
                got: format_type(&apply_subst(&ct, subst))
            } });
        }
    }

    // Arg #2: struct-form — must be a Vector literal or :wat::core::Vector call.
    match &args[1] {
        WatAST::Vector(elems, _) => {
            for elem in elems.iter() {
                let _ = infer(elem, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
            }
        }
        WatAST::List(items, _) => {
            let is_vector_head = matches!(
                items.first(),
                Some(WatAST::Keyword(k, _)) if k == ":wat::core::Vector"
            );
            if is_vector_head && items.len() > 1 {
                for elem in items[2..].iter() {
                    let _ = infer(elem, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
                }
            } else {
                let _ = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
            }
        }
        _ => {
            let _ = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
            local_errors.push(CheckError { span: args[1].span().clone(), kind: CheckErrorKind::MalformedForm {
                head: CALLEE.into(),
                reason: "struct_form (arg #2) must be a Vector literal `[...]` \
                         or a :wat::core::Vector expression"
                    .into(),
                remedies: vec![],
            } });
        }
    }

    // Arg #3: holon-form — must infer to :wat::holon::HolonAST.
    let holon_ty = infer(&args[2], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    if let Some(ht) = holon_ty {
        let expected_holon_ty = TypeExpr::Path(":wat::holon::HolonAST".into());
        if unify(&ht, &expected_holon_ty, subst, env.types()).is_err() {
            local_errors.push(CheckError { span: args[2].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: CALLEE.into(),
                param: "#3".into(),
                expected: ":wat::holon::HolonAST".into(),
                got: format_type(&apply_subst(&ht, subst))
            } });
        }
    }

    // Specific holon-record type from the static class (arc 258) — falls back to the
    // generic :wat::holon::Record when the class isn't a statically-known recordtype.
    let ty = record_of_specific_type(&args[0], env)
        .unwrap_or_else(|| TypeExpr::Path(":wat::holon::Record".into()));
    if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) }
}

/// Arc 097 slice 2 — polymorphic Instant ± Duration arithmetic.
///
/// Three valid shapes (LHS is always Instant):
///
/// ```text
/// (:wat::time::- Instant Duration) -> Instant
/// (:wat::time::- Instant Instant)  -> Duration
/// (:wat::time::+ Instant Duration) -> Instant
/// ```
///
/// The result type depends on (operator, RHS-variant). LHS-Duration
/// is rejected; we don't ship Duration arithmetic in this slice.
fn infer_polymorphic_time_arith(
    op: &str,
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    let instant_ty = TypeExpr::Path(":wat::time::Instant".into());
    let duration_ty = TypeExpr::Path(":wat::time::Duration".into());

    if args.len() != 2 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: op.into(),
            expected: 2,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        // HARVEST (236.2): existing diagnostic; time arith returns Instant as fallback.
        return CheckResult::partial_with(instant_ty, local_errors);
    }

    let a_ty = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    let b_ty = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    let a_resolved = a_ty.as_ref().map(|t| apply_subst(t, subst));
    let b_resolved = b_ty.as_ref().map(|t| apply_subst(t, subst));

    // LHS must be an Instant. Push a diagnostic if not, but continue
    // and pick a fallback result type so downstream inference doesn't
    // cascade.
    let a_is_instant = a_resolved
        .as_ref()
        .map(|t| matches!(t, TypeExpr::Path(p) if p == ":wat::time::Instant"))
        .unwrap_or(false);
    if !a_is_instant {
        if let Some(t) = &a_resolved {
            local_errors.push(CheckError { span: args[0].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: op.into(),
                param: "#1".into(),
                expected: ":wat::time::Instant".into(),
                got: format_type(t)
            } });
        }
    }

    // Dispatch on RHS variant.
    let ty = match (op, &b_resolved) {
        (":wat::time::-", Some(b))
            if matches!(b, TypeExpr::Path(p) if p == ":wat::time::Instant") =>
        {
            duration_ty
        }
        (":wat::time::-", Some(b))
            if matches!(b, TypeExpr::Path(p) if p == ":wat::time::Duration") =>
        {
            instant_ty
        }
        (":wat::time::+", Some(b))
            if matches!(b, TypeExpr::Path(p) if p == ":wat::time::Duration") =>
        {
            instant_ty
        }
        // RHS is something else — push a diagnostic, fall back to
        // Instant so downstream callers see a stable type.
        _ => {
            if let Some(t) = &b_resolved {
                let expected = if op == ":wat::time::+" {
                    ":wat::time::Duration"
                } else {
                    ":wat::time::Duration or :wat::time::Instant"
                };
                local_errors.push(CheckError { span: args[1].span().clone(), kind: CheckErrorKind::TypeMismatch {
                    callee: op.into(),
                    param: "#2".into(),
                    expected: expected.into(),
                    got: format_type(t)
                } });
            }
            instant_ty
        }
    };
    if local_errors.is_empty() { CheckResult::ok(ty) } else { CheckResult::partial_with(ty, local_errors) }
}

/// Arc 098 — type-check `:wat::form::matches?`. Substrate-recognized
/// special form (not a user defmacro); macros expand before
/// type-checking and can't query the struct registry, so the matcher
/// has to dispatch directly through `infer_call`.
///
/// Shape:
///
/// ```text
/// (:wat::form::matches? SUBJECT
///   (:TYPE-NAME (= ?var :field) ... <constraint> ...))
/// ```
///
/// The subject's static type is unconstrained — the matcher returns
/// `false` at runtime when the subject is `:None`, non-Struct, or a
/// Struct of the wrong type. We `infer` it anyway so nested errors
/// (e.g. unknown function in a nested call) still surface.
fn infer_form_matches(
    args: &[WatAST],
    head_span: &Span,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    let bool_ty = TypeExpr::Path(":wat::core::bool".into());

    if args.len() != 2 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: ":wat::form::matches?".into(),
            expected: 2,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        // HARVEST (236.2): existing diagnostic; matches? always returns bool.
        return CheckResult::partial_with(bool_ty, local_errors);
    }

    // Subject — drive nested errors but accept any type.
    let _ = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);

    // Pattern — must be `(:TYPE-NAME clause ...)`.
    let pattern_items = match &args[1] {
        WatAST::List(items, _) if !items.is_empty() => items,
        _ => {
            local_errors.push(CheckError { span: args[1].span().clone(), kind: CheckErrorKind::MalformedForm {
                head: ":wat::form::matches?".into(),
                reason: "pattern must be a list `(:TYPE-NAME clause ...)`".into(),
                remedies: vec![],
            } });
            // HARVEST (236.2): existing diagnostic; matches? always returns bool.
            return CheckResult::partial_with(bool_ty, local_errors);
        }
    };
    let type_name = match &pattern_items[0] {
        WatAST::Keyword(k, _) => k.as_str(),
        _ => {
            local_errors.push(CheckError { span: pattern_items[0].span().clone(), kind: CheckErrorKind::MalformedForm {
                head: ":wat::form::matches?".into(),
                reason: "pattern head must be a struct type keyword".into(),
                remedies: vec![],
            } });
            // HARVEST (236.2): existing diagnostic; matches? always returns bool.
            return CheckResult::partial_with(bool_ty, local_errors);
        }
    };

    // Resolve struct fields. Arc 293.2b — matches? only works on Struct aggregates.
    let fields: Vec<(String, TypeExpr)> = match env.types().get(type_name) {
        Some(crate::types::TypeDef::Aggregate(a)) if a.holder == crate::types::Holder::Struct => a.fields.clone(),
        Some(_) => {
            local_errors.push(CheckError { span: pattern_items[0].span().clone(), kind: CheckErrorKind::MalformedForm {
                head: ":wat::form::matches?".into(),
                reason: format!(
                    "pattern head {} names a non-struct type; matches? walks struct fields",
                    type_name
                ),
                remedies: vec![],
            } });
            // HARVEST (236.2): existing diagnostic; matches? always returns bool.
            return CheckResult::partial_with(bool_ty, local_errors);
        }
        None => {
            local_errors.push(CheckError { span: pattern_items[0].span().clone(), kind: CheckErrorKind::MalformedForm {
                head: ":wat::form::matches?".into(),
                reason: format!("unknown struct type {}", type_name),
                remedies: vec![],
            } });
            // HARVEST (236.2): existing diagnostic; matches? always returns bool.
            return CheckResult::partial_with(bool_ty, local_errors);
        }
    };

    // Walk clauses, threading binding scope through `pattern_locals`.
    // Bindings push `?var → field-type`; constraint sub-clauses
    // (and/or/not) re-use the same scope (sub-clauses cannot
    // introduce new bindings — see DESIGN §what's NOT in this arc).
    let mut pattern_locals = locals.clone();
    for clause in &pattern_items[1..] {
        check_clause(
            clause,
            type_name,
            &fields,
            env,
            &mut pattern_locals,
            fresh,
            subst,
            &mut local_errors,
        );
    }

    if local_errors.is_empty() { CheckResult::ok(bool_ty) } else { CheckResult::partial_with(bool_ty, local_errors) }
}

/// Type-check a single clause inside a `:wat::form::matches?`
/// pattern. Mutates `locals` to register fresh bindings; pushes
/// errors for grammar / semantic violations.
#[allow(clippy::too_many_arguments)]
fn check_clause(
    clause: &WatAST,
    type_name: &str,
    fields: &[(String, TypeExpr)],
    env: &CheckEnv,
    locals: &mut HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
    errors: &mut Vec<CheckError>,
) {
    use crate::form_match::{
        classify_clause, keyword_payload, logic_var_name, RawClause,
    };

    let raw = match classify_clause(clause) {
        Ok(r) => r,
        Err(e) => {
            errors.push(grammar_error_to_check_error(e, clause.span().clone()));
            return;
        }
    };

    match raw {
        RawClause::Eq { left, right } => {
            // Disambiguate binding vs equality by the LHS shape and
            // whether the variable is already in scope.
            // Stone 249.5e: recover the Identifier so we can key by env_key.
            if let WatAST::Symbol(ident, _) = left {
                if ident.as_str().starts_with('?') {
                    let var = logic_var_name(left).expect("Symbol starts with '?' — logic_var_name must return Some");
                    let env_key = crate::scope::resolution::env_key(ident);
                    if !locals.contains_key(env_key.as_ref()) {
                    // Fresh ?var — this is a binding. RHS must be a
                    // field keyword that exists on the struct.
                    let field_name = match keyword_payload(right) {
                        Some(k) => k,
                        None => {
                            errors.push(CheckError { span: right.span().clone(), kind: CheckErrorKind::MalformedForm {
                                head: ":wat::form::matches?".into(),
                                reason: format!(
                                    "binding RHS for {} must be a field keyword like :field-name",
                                    var
                                ),
                                remedies: vec![],
                            } });
                            return;
                        }
                    };
                    // Field name is the keyword stripped of leading `:`.
                    let field_lookup = field_name.strip_prefix(':').unwrap_or(field_name);
                    let field_ty = match fields.iter().find(|(n, _)| n == field_lookup) {
                        Some((_, t)) => t.clone(),
                        None => {
                            errors.push(CheckError { span: right.span().clone(), kind: CheckErrorKind::MalformedForm {
                                head: ":wat::form::matches?".into(),
                                reason: format!(
                                    "struct {} has no field {}",
                                    type_name, field_name
                                ),
                                remedies: vec![],
                            } });
                            return;
                        }
                    };
                    locals.insert(env_key.into_owned(), field_ty);
                    return;
                }
                    // ?var already bound — fall through to comparison.
                }
            }
            // LHS isn't a ?var, or is already bound — fall through to comparison.
            check_comparison(left, right, env, locals, fresh, subst, errors);
        }
        RawClause::Compare { left, right, .. } => {
            check_comparison(left, right, env, locals, fresh, subst, errors);
        }
        RawClause::And(subs) | RawClause::Or(subs) => {
            for sub in subs {
                check_clause(sub, type_name, fields, env, locals, fresh, subst, errors);
            }
        }
        RawClause::Not(sub) => {
            check_clause(sub, type_name, fields, env, locals, fresh, subst, errors);
        }
        RawClause::Where(body) => {
            // `where` body is arbitrary wat in the binding scope;
            // it must type to `:bool`.
            let body_ty = infer(body, env, locals, fresh, subst).drain_errors_into(errors);
            if let Some(t) = body_ty {
                let bool_ty = TypeExpr::Path(":wat::core::bool".into());
                if unify(&t, &bool_ty, subst, env.types()).is_err() {
                    errors.push(CheckError { span: body.span().clone(), kind: CheckErrorKind::TypeMismatch {
                        callee: ":wat::form::matches?".into(),
                        param: "where-body".into(),
                        expected: format_type(&bool_ty),
                        got: format_type(&apply_subst(&t, subst))
                    } });
                }
            }
        }
    }
}

/// Type-check the two operands of a comparison clause. Both sides
/// are inferred; if both have known types, they must unify to a
/// common type (matches arc 050 polymorphic-compare semantics).
fn check_comparison(
    left: &WatAST,
    right: &WatAST,
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
    errors: &mut Vec<CheckError>,
) {
    let l_ty = infer(left, env, locals, fresh, subst).drain_errors_into(errors);
    let r_ty = infer(right, env, locals, fresh, subst).drain_errors_into(errors);
    if let (Some(l), Some(r)) = (l_ty, r_ty) {
        if unify(&l, &r, subst, env.types()).is_err() {
            errors.push(CheckError { span: right.span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: ":wat::form::matches?".into(),
                param: "comparison".into(),
                expected: format_type(&apply_subst(&l, subst)),
                got: format_type(&apply_subst(&r, subst))
            } });
        }
    }
}

fn grammar_error_to_check_error(e: crate::form_match::ClauseGrammarError, span: Span) -> CheckError {
    use crate::form_match::ClauseGrammarErrorKind as G;
    let reason = match e.kind {
        G::NotAList => "clause must be a list `(head ...)`".to_string(),
        G::EmptyList => "empty clause `()` — clauses need a head".to_string(),
        G::NonKeywordHead => "clause head must be a keyword (=, <, and, where, ...)".to_string(),
        G::UnknownHead(h) => format!(
            "unknown matcher head: {}; recognized: =, <, >, <=, >=, not=, and, or, not, where",
            h
        ),
        G::NotArity { got, .. } => format!("`not` takes exactly 1 sub-clause; got {}", got),
        G::WhereArity { got, .. } => format!("`where` takes exactly 1 expression; got {}", got),
        G::BinaryArity { op, got, .. } => format!("`{}` takes exactly 2 args; got {}", op.as_str(), got),
    };
    CheckError { span, kind: CheckErrorKind::MalformedForm {
        head: ":wat::form::matches?".into(),
        reason,
        remedies: vec![],
    } }
}


/// Arc 052 — predicate. Recognizes `:wat::holon::HolonAST` and
/// `:wat::holon::Vector` — the two algebra-tier value types accepted
/// by polymorphic cosine / dot / simhash.
fn is_holon_or_vector(t: &TypeExpr, types: &crate::types::TypeEnv) -> bool {
    // Arc 234 Stone 234.5 — extended to accept :wat::core::Record.
    // Arc 237 Stone S-C.3 — extended to accept :wat::holon::Record (holonic variant).
    // Arc 258 cascade — extended to accept any subtype of :wat::core::Record or
    // :wat::holon::Record (specifically-typed records, e.g. :myapp::Pt).
    // Records carry a pre-built holon_form; the runtime auto-dispatches via
    // pair_values_to_vectors (coerce_to_holon_ast pattern). Cosine and dot
    // accept records natively; the hologram property makes them VSA operands.
    match t {
        TypeExpr::Path(p)
            if p == ":wat::holon::HolonAST"
                || p == ":wat::holon::Vector"
                || crate::types::is_subtype(p, ":wat::core::Record", types)
                || crate::types::is_subtype(p, ":wat::holon::Record", types) =>
        {
            true
        }
        _ => false,
    }
}

/// Arc 052 — polymorphic two-arg holon-algebra inference.
///
/// For `:wat::holon::cosine` and `:wat::holon::dot`. Both args must be
/// HolonAST or Vector; result type is `:f64`. Mixed inputs are
/// permitted (the runtime promotes the AST side by encoding at the
/// Vector side's d).
fn infer_polymorphic_holon_pair_to_f64(
    op: &str,
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    let f64_ty = TypeExpr::Path(":wat::core::f64".into());
    if args.len() != 2 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: op.into(),
            expected: 2,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        // HARVEST (236.2): existing diagnostic; holon pair ops return f64.
        return CheckResult::partial_with(f64_ty, local_errors);
    }
    let a_ty = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    let b_ty = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    if let Some(t) = &a_ty {
        let resolved = apply_subst(t, subst);
        // Arc 294.a — widen: accept any EDN-representable value (portable type) in addition
        // to the algebra-native types. The runtime lifts via to_holon_inner internally.
        if !is_holon_or_vector(&resolved, env.types()) && !is_portable_type(&resolved, env.types()) {
            local_errors.push(CheckError { span: args[0].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: op.into(),
                param: "#1".into(),
                expected: ":wat::holon::HolonAST | :wat::holon::Vector | any EDN-representable value".into(),
                got: format_type(&resolved)
            } });
        }
    }
    if let Some(t) = &b_ty {
        let resolved = apply_subst(t, subst);
        // Arc 294.a — widen: accept any EDN-representable value (portable type) in addition
        // to the algebra-native types. The runtime lifts via to_holon_inner internally.
        if !is_holon_or_vector(&resolved, env.types()) && !is_portable_type(&resolved, env.types()) {
            local_errors.push(CheckError { span: args[1].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: op.into(),
                param: "#2".into(),
                expected: ":wat::holon::HolonAST | :wat::holon::Vector | any EDN-representable value".into(),
                got: format_type(&resolved)
            } });
        }
    }
    if local_errors.is_empty() { CheckResult::ok(f64_ty) } else { CheckResult::partial_with(f64_ty, local_errors) }
}

/// Arc 234 Stone 234.5 — custom inference handler for `:wat::holon::Bind`.
///
/// Extends the TypeScheme (which accepted only `:wat::holon::HolonAST` in
/// both positions) to also accept `:wat::core::Record`. The runtime auto-dispatches
/// via `coerce_to_holon_ast`; the check layer mirrors this polymorphism.
///
/// Pattern: per `infer_record_of` (Stone 234.2a-CORRECTION) and
/// `infer_polymorphic_holon_pair_to_f64` (arc 052). Custom dispatch arm in
/// `match k.as_str()` takes precedence over the TypeScheme registration
/// at line 14311 (which becomes dead code for `:wat::holon::Bind` calls
/// when this arm is present; it is retained as documentation).
fn infer_holon_bind(
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    let holon_ty = TypeExpr::Path(":wat::holon::HolonAST".into());
    if args.len() != 2 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: ":wat::holon::Bind".into(),
            expected: 2,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        // HARVEST (236.2): existing diagnostic; Bind returns HolonAST.
        return CheckResult::partial_with(holon_ty, local_errors);
    }
    // Infer both args; accept HolonAST or wat::core::Record in either position.
    // is_holon_or_vector now includes :wat::core::Record (Stone 234.5).
    for (idx, arg) in args.iter().enumerate() {
        if let Some(t) = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
            let resolved = apply_subst(&t, subst);
            if !is_holon_or_record(&resolved, env.types()) {
                local_errors.push(CheckError { span: arg.span().clone(), kind: CheckErrorKind::TypeMismatch {
                    callee: ":wat::holon::Bind".into(),
                    param: format!("#{}", idx + 1),
                    expected: ":wat::holon::HolonAST or :wat::core::Record".into(),
                    got: format_type(&resolved)
                } });
            }
        }
    }
    if local_errors.is_empty() { CheckResult::ok(holon_ty) } else { CheckResult::partial_with(holon_ty, local_errors) }
}

/// Arc 234 Stone 234.5 — predicate. Recognizes `:wat::holon::HolonAST`
/// and `:wat::core::Record` — the two types accepted in Bind/Bundle arg positions after
/// Stone 234.5. Distinct from `is_holon_or_vector` (which also accepts
/// `:wat::holon::Vector` for the cosine/dot algebra verbs).
/// Arc 237 Stone S-C.3 — extended to also accept `:wat::holon::Record`
/// (holonic variant; subtype of `:wat::core::Record`).
/// Arc 258 cascade — extended to accept any subtype of :wat::core::Record or
/// :wat::holon::Record (specifically-typed records, e.g. :myapp::Voltage).
fn is_holon_or_record(t: &TypeExpr, types: &crate::types::TypeEnv) -> bool {
    match t {
        TypeExpr::Path(p)
            if p == ":wat::holon::HolonAST"
                || crate::types::is_subtype(p, ":wat::core::Record", types)
                || crate::types::is_subtype(p, ":wat::holon::Record", types) =>
        {
            true
        }
        _ => false,
    }
}

/// Arc 254 Stone 254.1 — type-level portability predicate for channel payloads.
///
/// A type is portable (wire-serializable / universe-crossable) iff it can be
/// reconstructed in a fresh world. Mirrors `closure_extract.rs`'s value-level
/// split in `encode_value_with_path` (portable arms ~1492-1544; non-portable
/// arms ~1729-1745).
///
/// Classification:
/// - **Portable scalars** (Path): `i64`, `f64`, `bool`, `u8`, `String`,
///   `keyword`, `Uuid`, `Char`, `nil` — exactly the primitive arms of the
///   value-level encoder.
/// - **Portable containers** (Parametric with portable element types):
///   `Vector`, `List`, `HashMap`, `HashSet`, `Option`, `Result`, `Tuple`.
/// - **Tuples**: all elements must be portable.
/// - **User types** (Path resolved via TypeEnv):
///   - `TypeDef::Aggregate(kind=Record|HolonRecord)` — portable by construction (holon-representable).
///   - `TypeDef::Aggregate(kind=Struct)` — categorically non-portable (structs never cross the wire).
///   - `TypeDef::Enum` — portable iff every variant's field types are portable.
///   - `TypeDef::Newtype` — portable iff inner type is portable.
///   - `TypeDef::Alias` — transparent (expand_alias handles this in `reduce`).
///   - `TypeDef::Union` — conservative: false (union members may be non-portable).
/// - **Non-portable** (Parametric with non-portable head regardless of args):
///   `Sender`, `Receiver`, `ProgramHandle`, `HandlePool`.
/// - **Non-portable** (Path): `ChildHandle`, `IOReader`, `IOWriter`,
///   `OnlineSubspace`, `Reckoner`, `Engram`, `EngramLibrary`, `Hologram`.
/// - `TypeExpr::Fn` — closures never cross universe boundaries.
/// - `TypeExpr::Var` — unresolved type variable; conservatively non-portable.
fn is_portable_type(ty: &TypeExpr, types: &TypeEnv) -> bool {
    // Canonicalize: expand aliases and walk through any substitution.
    let ty = reduce(ty, &Subst::new(), types);
    match &ty {
        TypeExpr::Fn { .. } => false,
        TypeExpr::Var(_) => false,
        TypeExpr::Tuple(elems) => elems.iter().all(|e| is_portable_type(e, types)),
        TypeExpr::Parametric { head, args } => {
            // Non-portable parametric heads regardless of type args.
            match head.as_str() {
                "rust::crossbeam_channel::Sender"
                | "rust::crossbeam_channel::Receiver"
                | "wat::kernel::Sender"
                | "wat::kernel::Receiver"
                | "wat::kernel::ProgramHandle"
                | "wat::kernel::HandlePool" => false,
                // Portable container: portable iff all type args are portable.
                // Vector<T>, List<T>, Option<T>, Result<T,E>, HashMap<K,V>,
                // HashSet<T>, Tuple<...> — any other parametric is conservatively
                // portable-if-args-portable (falls through to the arg check).
                _ => args.iter().all(|a| is_portable_type(a, types)),
            }
        }
        TypeExpr::Path(p) => {
            // Strip leading ':' for TypeEnv lookup.
            let bare = p.strip_prefix(':').unwrap_or(p.as_str());
            // Well-known non-portable opaque paths (not parametric).
            match bare {
                "wat::kernel::ChildHandle"
                | "wat::io::IOReader"
                | "wat::io::IOWriter"
                | "wat::holon::OnlineSubspace"
                | "wat::holon::Reckoner"
                | "wat::holon::Engram"
                | "wat::holon::EngramLibrary"
                | "wat::holon::Hologram" => return false,
                _ => {}
            }
            // Well-known portable scalar paths.
            match bare {
                "wat::core::i64"
                | "wat::core::f64"
                | "wat::core::bool"
                | "wat::core::u8"
                | "wat::core::String"
                | "wat::core::keyword"
                | "wat::core::Uuid"
                | "wat::core::char"
                | "wat::core::nil"
                | "wat::core::unit" => return true,
                _ => {}
            }
            // Look up user-defined types.
            match types.get(p) {
                // Arc 293.2b — Holder::is_portable() encodes the wire wall:
                // Record | HolonRecord → portable; Struct → non-portable.
                Some(crate::types::TypeDef::Aggregate(a)) => a.holder.is_portable(),
                // Enum: treated as portable at the type level. Enum variant
                // fields may include Receiver<T> in substrate service-control
                // enums (e.g. StdOutService::Event) — recursing into them
                // would over-reject legitimate stdlib usage. The probe target
                // (254.1) is struct payloads with direct non-portable fields;
                // enum payload portability is not yet enforced.
                Some(crate::types::TypeDef::Enum(_)) => true,
                // Newtype: portable iff inner type is portable.
                Some(crate::types::TypeDef::Newtype(n)) => {
                    is_portable_type(&n.inner, types)
                }
                // Alias: expand_alias in reduce should have handled this;
                // treat remaining as portable (alias will have been expanded).
                Some(crate::types::TypeDef::Alias(_)) => true,
                // Union: conservative — members may include non-portable types.
                Some(crate::types::TypeDef::Union(_)) => false,
                // Arc 293.3-core — Surface is a structural interface, not a concrete value type.
                // The actual value flowing through a surface-typed parameter is a struct;
                // the surface itself is not a portable concrete type. Conservative false.
                Some(crate::types::TypeDef::Surface(_)) => false,
                // Unknown path — this is a formal type parameter (e.g. `:T`
                // in a parametric function body). Type parameters are
                // portable by convention: portability of the concrete type
                // is enforced at each instantiation site. Treat as portable.
                None => true,
            }
        }
    }
}

/// Arc 234 Stone 234.5 — custom inference handler for `:wat::holon::Bundle`.
///
/// Extends Bundle to accept a `Vector<T>` where each element T is either
/// `:wat::holon::HolonAST` or `:wat::core::Record`. The TypeScheme (line 14328)
/// declared `Vector<HolonAST>` and is retained as documentation; this
/// dispatch arm supersedes it.
///
/// The element-level check mirrors `infer_record_of`'s heterogeneous-vec
/// pattern (Stone 234.2a-CORRECTION): each element is inferred independently
/// without cross-element unification, then validated against `is_holon_or_record`.
fn infer_holon_bundle(
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    let result_ty = TypeExpr::Parametric {
        head: "wat::core::Result".into(),
        args: vec![
            TypeExpr::Path(":wat::holon::HolonAST".into()),
            TypeExpr::Path(":wat::holon::CapacityExceeded".into()),
        ],
    };
    if args.len() != 1 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: ":wat::holon::Bundle".into(),
            expected: 1,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        // HARVEST (236.2): existing diagnostic; Bundle returns Result<HolonAST, CapacityExceeded>.
        return CheckResult::partial_with(result_ty, local_errors);
    }
    // Inspect the single arg — expect a Vector literal or :wat::core::vec call.
    // Elements can be HolonAST or wat::core::Record (Stone 234.5 extension).
    // Mirror infer_record_of's element-level independent inference.
    match &args[0] {
        WatAST::Vector(elems, _) => {
            for elem in elems {
                if let Some(t) = infer(elem, env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
                    let resolved = apply_subst(&t, subst);
                    if !is_holon_or_record(&resolved, env.types()) {
                        local_errors.push(CheckError { span: elem.span().clone(), kind: CheckErrorKind::TypeMismatch {
                            callee: ":wat::holon::Bundle".into(),
                            param: "list element".into(),
                            expected: ":wat::holon::HolonAST or :wat::core::Record".into(),
                            got: format_type(&resolved)
                        } });
                    }
                }
            }
        }
        other => {
            // General expression: infer then validate it's a Vector<T> where T is
            // HolonAST or Record. For non-literal args, the TypeScheme's element
            // type constraint must still be enforced at the call site.
            // Pre-Stone-234.5 TypeScheme said Vector<HolonAST>; we now also accept
            // Vector<Record>. Any other Vector<T> is rejected (TypeMismatch).
            // Use reduce (not apply_subst) so typealiases like :wat::holon::Holons
            // (= Vector<HolonAST>) unfold before the structural match.
            if let Some(t) = infer(other, env, locals, fresh, subst).drain_errors_into(&mut local_errors) {
                let resolved = reduce(&t, subst, env.types());
                let ok = match &resolved {
                    TypeExpr::Parametric { head, args: ta } if head == "wat::core::Vector" => {
                        ta.len() == 1 && is_holon_or_record(&ta[0], env.types())
                    }
                    _ => false,
                };
                if !ok {
                    local_errors.push(CheckError { span: other.span().clone(), kind: CheckErrorKind::TypeMismatch {
                        callee: ":wat::holon::Bundle".into(),
                        param: "#1".into(),
                        expected: "wat::core::Vector<:wat::holon::HolonAST> or wat::core::Vector<:wat::core::Record>".into(),
                        got: format_type(&resolved)
                    } });
                }
            }
        }
    }
    if local_errors.is_empty() { CheckResult::ok(result_ty) } else { CheckResult::partial_with(result_ty, local_errors) }
}

/// Arc 061 — polymorphic two-arg holon-algebra inference returning
/// `:bool`. For `:wat::holon::coincident?` — accepts HolonAST or
/// Vector in either position. Mirrors
/// [`infer_polymorphic_holon_pair_to_f64`] exactly; differs only in
/// return type.
fn infer_polymorphic_holon_pair_to_bool(
    op: &str,
    head_span: &Span,
    args: &[WatAST],
    env: &CheckEnv,
    locals: &HashMap<String, TypeExpr>,
    fresh: &mut InferCtx,
    subst: &mut Subst,
) -> CheckResult<TypeExpr> {
    let mut local_errors: Vec<CheckError> = Vec::new();
    let bool_ty = TypeExpr::Path(":wat::core::bool".into());
    if args.len() != 2 {
        local_errors.push(CheckError { span: head_span.clone(), kind: CheckErrorKind::ArityMismatch {
            callee: op.into(),
            expected: 2,
            got: args.len()
        } });
        for arg in args {
            let _ = infer(arg, env, locals, fresh, subst).drain_errors_into(&mut local_errors);
        }
        // HARVEST (236.2): existing diagnostic; holon pair ops return bool.
        return CheckResult::partial_with(bool_ty, local_errors);
    }
    let a_ty = infer(&args[0], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    let b_ty = infer(&args[1], env, locals, fresh, subst).drain_errors_into(&mut local_errors);
    if let Some(t) = &a_ty {
        let resolved = apply_subst(t, subst);
        // Arc 294.a — widen: accept any EDN-representable value (portable type).
        if !is_holon_or_vector(&resolved, env.types()) && !is_portable_type(&resolved, env.types()) {
            local_errors.push(CheckError { span: args[0].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: op.into(),
                param: "#1".into(),
                expected: ":wat::holon::HolonAST | :wat::holon::Vector | any EDN-representable value".into(),
                got: format_type(&resolved)
            } });
        }
    }
    if let Some(t) = &b_ty {
        let resolved = apply_subst(t, subst);
        // Arc 294.a — widen: accept any EDN-representable value (portable type).
        if !is_holon_or_vector(&resolved, env.types()) && !is_portable_type(&resolved, env.types()) {
            local_errors.push(CheckError { span: args[1].span().clone(), kind: CheckErrorKind::TypeMismatch {
                callee: op.into(),
                param: "#2".into(),
                expected: ":wat::holon::HolonAST | :wat::holon::Vector | any EDN-representable value".into(),
                got: format_type(&resolved)
            } });
        }
    }
    if local_errors.is_empty() { CheckResult::ok(bool_ty) } else { CheckResult::partial_with(bool_ty, local_errors) }
}

